import json
from collections import Counter
from scripts import diag_p106b_evidence_recovery_course as c
from tinylm.train.mtp_sft import encode_record
conversation_signature=c.conversation_signature
r=c.producer.required(c.CORPUS/"report.json");tok=c.old._tokenizer();arms={}
for arm in c.ARMS:
 unique={};draw=Counter();langs={}
 for epoch in range(4):
  key=arm+"_train"+str(epoch);summary=r["counts"][key]
  draw.update({k:summary[k] for k in ("rows","x_tokens","assistant_targets")})
  for lang,v in summary["languages"].items():langs.setdefault(lang,Counter()).update(v)
  for row in c.training.data.stream_rows(c.CORPUS,r["manifests"][key]):
   sig=conversation_signature(row["messages"])
   if sig not in unique:unique[sig]=encode_record(row,tok).x_tokens
 actual=c.producer.required(c.EVIDENCE/arm/"report.json")
 assert (draw["x_tokens"],draw["assistant_targets"])==(actual["sft_x_tokens"],actual["assistant_targets"])
 arms[arm]=dict(total_draws=dict(draw),distinct_serialized_conversations=dict(serialized_conversations=len(unique),serialized_x_tokens=sum(unique.values())),language_draws={k:dict(v) for k,v in langs.items()})
print(json.dumps(dict(schema="P106B_EVIDENCE_RECOVERY_SERIALIZED_EXPOSURE_POSTHOC_V1",arms=arms,course_sha256=c.training.data.digest(c.CORPUS/"report.json"),scope="Frozen conversations and real student encoder, actual complete report counts matched. Distinct text not new world facts; language counts are frozen producer recount, not GPU sampling. No model/forward/optimizer/CUDA.")))
